54	async function applyStoredAppearance(backgroundOverride = null) {
55	  const generation = ++appearanceGeneration;
56	  let bg = backgroundOverride;
57	
58	  if (!bg) {
59	    const { theme, background } = await chrome.storage.sync.get([
60	      "theme",
61	      "background",
62	    ]);
63	    if (generation !== appearanceGeneration) return;
64	    applyTheme(theme ?? "system");
65	    bg = background ?? DEFAULT_BACKGROUND;
66	  }
67	
68	  const customUrlPromise =
69	    bg.type === "custom" ? getCustomBackgroundUrl() : null;
70	  applyAccentFromBackground(bg, customUrlPromise);
71	  const customUrl = customUrlPromise ? await customUrlPromise : null;
72	  if (generation !== appearanceGeneration) return;
73	  applyBackground(bg, customUrl);
74	}
