76	function setupLightbox() {
77	  const lightbox = document.getElementById("tab-lightbox");
78	  const thumbEl = document.getElementById("lightbox-thumbnail");
79	  const placeholderEl = document.getElementById("lightbox-placeholder");
80	  const faviconEl = document.getElementById("lightbox-favicon");
81	  const titleEl = document.getElementById("lightbox-title");
82	  const urlEl = document.getElementById("lightbox-url");
83	  const LIGHTBOX_W = 400;
84	  const MARGIN = 8;
85	  let currentTab = null;
86	  let closeTimer = null;
87	
88	  function navigate() {
89	    if (currentTab) activateTab(currentTab.id);
90	    hideLightbox();
91	  }
92	
93	  function showLightbox({ tab, thumbnail, rect }) {
94	    currentTab = tab;
95	    clearTimeout(closeTimer);
96	
97	    if (thumbnail) {
98	      thumbEl.src = thumbnail;
99	      thumbEl.classList.remove("hidden");
100	      placeholderEl.classList.add("hidden");
101	    } else {
102	      thumbEl.src = "";
103	      thumbEl.classList.add("hidden");
104	      placeholderEl.textContent = (tab.title || "?").charAt(0).toUpperCase();
105	      placeholderEl.classList.remove("hidden");
106	    }
107	
108	    if (tab.favIconUrl) {
109	      faviconEl.src = tab.favIconUrl;
110	    }
111	    faviconEl.classList.toggle("hidden", !tab.favIconUrl);
112	
113	    titleEl.textContent = tab.title || tab.url || "New Tab";
114	    urlEl.textContent = tab.url || "";
115	
116	    const vw = window.innerWidth;
117	    const vh = window.innerHeight;
118	    // thumbnail height + body section (title + meta + padding)
119	    const approxH = Math.round((LIGHTBOX_W * 10) / 16) + 80;
120	
121	    // Center both horizontally and vertically on the card
122	    const cardCX = rect.left + rect.width / 2;
123	    const cardCY = rect.top + rect.height / 2;
124	
125	    let left = cardCX - LIGHTBOX_W / 2;
126	    left = Math.max(MARGIN, Math.min(left, vw - LIGHTBOX_W - MARGIN));
127	
128	    let top = cardCY - approxH / 2;
129	    top = Math.max(MARGIN, Math.min(top, vh - approxH - MARGIN));
130	
131	    // Transform-origin at the card's center so it appears to grow from the card
132	    const originX = Math.round(
133	      ((rect.left + rect.width / 2 - left) / LIGHTBOX_W) * 100,
134	    );
135	    const originY = Math.round(
136	      ((rect.top + rect.height / 2 - top) / approxH) * 100,
137	    );
138	    lightbox.style.setProperty("--lightbox-origin-x", `${originX}%`);
139	    lightbox.style.setProperty("--lightbox-origin-y", `${originY}%`);
140	    lightbox.style.setProperty("--lightbox-left", `${left}px`);
141	    lightbox.style.setProperty("--lightbox-top", `${top}px`);
142	    lightbox.classList.remove("hidden");
143	  }
144	
145	  function hideLightbox() {
146	    lightbox.classList.add("hidden");
147	    currentTab = null;
148	  }
149	
150	  lightbox.addEventListener("mouseleave", () => {
151	    closeTimer = setTimeout(hideLightbox, 150);
152	  });
153	  lightbox.addEventListener("mouseenter", () => clearTimeout(closeTimer));
154	
155	  lightbox.addEventListener("click", navigate);
156	
157	  document.addEventListener("tab-lightbox-show", (e) => {
158	    // Suppress the hover preview while a context menu is open (same intent as
159	    // hovering the tab's close "X").
160	    if (isContextMenuOpen()) return;
161	    showLightbox(e.detail);
162	  });
163	  document.addEventListener("dragstart", hideLightbox);
164	
165	  return {
166	    hide: hideLightbox,
167	    isVisible: () => !lightbox.classList.contains("hidden"),
168	  };
169	}
