171	async function getWindowMeridianTabId(currentTab) {
172	  if (!currentTab) return null;
173	  const stored = await chrome.storage.local.get([
174	    "meridianTabIds",
175	    "meridianTabId",
176	  ]);
177	  const candidates = [
178	    stored.meridianTabIds?.[String(currentTab.windowId)],
179	    stored.meridianTabId,
180	  ].filter((id) => Number.isInteger(id));
181	
182	  for (const id of candidates) {
183	    try {
184	      const tab = await chrome.tabs.get(id);
185	      if (tab.windowId === currentTab.windowId) return id;
186	    } catch (_) {
187	      /* stale stored id */
188	    }
189	  }
190	
191	  const pinnedTabs = await chrome.tabs.query({
192	    pinned: true,
193	    windowId: currentTab.windowId,
194	  });
195	  const meridianUrl = chrome.runtime.getURL("meridian.html");
196	  return (
197	    pinnedTabs.find(
198	      (tab) =>
199	        tab.url === meridianUrl ||
200	        tab.pendingUrl === meridianUrl ||
201	        tab.url === "chrome://newtab/" ||
202	        tab.pendingUrl === "chrome://newtab/",
203	    )?.id ?? null
204	  );
205	}
