207	async function handleNewTabBehavior() {
208	  const [newTabBehavior, { homepageUrl }] = await Promise.all([
209	    getNewTabBehavior(),
210	    chrome.storage.sync.get("homepageUrl"),
211	  ]);
212	  if (newTabBehavior === "focus-pinned") {
213	    const currentTab = await chrome.tabs.getCurrent();
214	    const meridianTabId = await getWindowMeridianTabId(currentTab);
215	    if (meridianTabId && currentTab && meridianTabId !== currentTab.id) {
216	      await activateTab(meridianTabId);
217	      window.close();
218	    }
219	  } else if (newTabBehavior === "open-homepage") {
220	    const normalizedHomepage = normalizeHomepageUrl(homepageUrl ?? "");
221	    if (!normalizedHomepage) return;
222	
223	    const currentTab = await chrome.tabs.getCurrent();
224	    const meridianTabId = await getWindowMeridianTabId(currentTab);
225	    if (!currentTab || currentTab.id === meridianTabId) return;
226	    try {
227	      await chrome.tabs.update(currentTab.id, { url: normalizedHomepage });
228	    } catch (error) {
229	      console.warn("Could not open the configured homepage.", error);
230	    }
231	  }
232	}
