241	function setupKeyboardNav() {
242	  document.addEventListener("keydown", (e) => {
243	    const tag = document.activeElement?.tagName;
244	    const isEditing =
245	      tag === "INPUT" ||
246	      tag === "TEXTAREA" ||
247	      document.activeElement?.contentEditable === "true";
248	
249	    if (e.key === "/" && !isEditing) {
250	      e.preventDefault();
251	      searchBarApi?.focus();
252	      return;
253	    }
254	
255	    if (e.key === "Escape") {
256	      if (lightboxApi?.isVisible()) {
257	        lightboxApi.hide();
258	        return;
259	      }
260	      if (settingsPopup?.isOpen()) {
261	        closeSettings();
262	        return;
263	      }
264	      if (browserSearchActive) {
265	        clearBrowserSearch();
266	        searchBarApi?.clearSearch?.();
267	        return;
268	      }
269	      if (document.activeElement?.tagName === "INPUT") {
270	        document.activeElement.blur();
271	        focusFirstCard();
272	      }
273	      return;
274	    }
275	
276	    if (["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown"].includes(e.key)) {
277	      if (isEditing) return;
278	      e.preventDefault();
279	      navigateCards(e.key);
280	    }
281	  });
282	}
