284	function navigateCards(key) {
285	  const cards = [...document.querySelectorAll(".tab-card")];
286	  if (!cards.length) return;
287	  const focused = document.activeElement;
288	  if (!cards.includes(focused)) {
289	    cards[0].focus();
290	    return;
291	  }
292	
293	  const grid = focused.closest(".tab-grid");
294	  const lane = focused.closest(".workspace-lane");
295	  const gridCards = [...grid.querySelectorAll(".tab-card")];
296	  const gridIdx = gridCards.indexOf(focused);
297	
298	  let next = null;
299	  if (key === "ArrowRight") next = gridCards[gridIdx + 1] ?? null;
300	  if (key === "ArrowLeft") next = gridIdx > 0 ? gridCards[gridIdx - 1] : null;
301	
302	  if (key === "ArrowDown" || key === "ArrowUp") {
303	    const lanes = [...document.querySelectorAll(".workspace-lane")];
304	    const laneIdx = lanes.indexOf(lane);
305	    const targetLane =
306	      key === "ArrowDown" ? lanes[laneIdx + 1] : lanes[laneIdx - 1];
307	    if (targetLane) next = targetLane.querySelector(".tab-card");
308	  }
309	
310	  next?.focus();
311	}
