351	function scheduleRender() {
352	  // Replacing the lane DOM during a native drag removes the source element,
353	  // which prevents `dragend` from firing and leaves Meridian stuck in its drag
354	  // state. Hold browser/storage-driven renders until the gesture is finished.
355	  if (isTabDragActive()) {
356	    renderDeferredByDrag = true;
357	    return;
358	  }
359	
360	  clearTimeout(renderTimer);
361	  renderTimer = setTimeout(async () => {
362	    if (isTabDragActive()) {
363	      renderDeferredByDrag = true;
364	      return;
365	    }
366	    if (renderRunning) {
367	      scheduleRender();
368	      return;
369	    }
370	    renderRunning = true;
371	    try {
372	      await render();
373	    } finally {
374	      renderRunning = false;
375	    }
376	  }, 50);
377	}
378	
379	function flushDeferredDragRender() {
380	  if (!renderDeferredByDrag) return;
381	  renderDeferredByDrag = false;
382	  scheduleRender();
383	}
