385	function sortByTabOrder(tabs, order) {
386	  if (!order?.length) return tabs;
387	  const pos = new Map(order.map((id, i) => [id, i]));
388	  return [...tabs].sort(
389	    (a, b) => (pos.get(a.id) ?? Infinity) - (pos.get(b.id) ?? Infinity),
390	  );
391	}
