393	async function render() {
394	  const container = document.getElementById("workspace-container");
395	  container.innerHTML = "";
396	
397	  const { groupByDomain } = await chrome.storage.sync.get("groupByDomain");
398	
399	  const chromeGroupsPromise = hasNativeGroups
400	    ? chrome.tabGroups.query({})
401	    : Promise.resolve([]);
402	
403	  const [allTabs, chromeGroups, thumbnails, currentTab, wsData, localStore] =
404	    await Promise.all([
405	      chrome.tabs.query({}),
406	      chromeGroupsPromise,
407	      getAllThumbnails(),
408	      chrome.tabs.getCurrent(),
409	      getWorkspaceData(),
410	      chrome.storage.local.get(["collapsedLanes", "tabOrder"]),
411	    ]);
412	  const collapsedLanes = localStore.collapsedLanes ?? {};
413	  const tabOrder = localStore.tabOrder ?? {};
414	
415	  const meridianUrl = chrome.runtime.getURL("meridian.html");
416	  const visibleTabs = allTabs.filter(
417	    (t) =>
418	      t.id !== currentTab?.id &&
419	      t.url !== meridianUrl &&
420	      t.pendingUrl !== meridianUrl &&
421	      t.url !== "chrome://newtab/" &&
422	      t.pendingUrl !== "chrome://newtab/",
423	  );
424	
425	  const groupMap = new Map(chromeGroups.map((g) => [g.id, g]));
426	  const chromeGroupedMap = new Map();
427	  const ungroupedTabs = [];
428	
429	  for (const tab of visibleTabs) {
430	    if (hasNativeGroups && tab.groupId !== -1) {
431	      if (!chromeGroupedMap.has(tab.groupId))
432	        chromeGroupedMap.set(tab.groupId, []);
433	      chromeGroupedMap.get(tab.groupId).push(tab);
434	    } else {
435	      ungroupedTabs.push(tab);
436	    }
437	  }
438	
439	  // Distribute ungrouped tabs into Meridian workspaces
440	  const customWorkspaces = wsData.workspaces.filter((w) => w.id !== "unsorted");
441	  const wsTabMap = new Map(customWorkspaces.map((w) => [w.id, []]));
442	  const trulyUnsorted = [];
443	
444	  for (const tab of ungroupedTabs) {
445	    const wsId = wsData.assignments[String(tab.id)];
446	    if (wsId && wsTabMap.has(wsId)) {
447	      wsTabMap.get(wsId).push(tab);
448	    } else {
449	      trulyUnsorted.push(tab);
450	    }
451	  }
452	
453	  // 1. Unsorted / domain clusters first
454	  if (groupByDomain) {
455	    const clusters = clusterTabsByDomain(trulyUnsorted);
456	    for (const [name, clusterTabs] of clusters) {
457	      const workspace = { id: `dc_${name}`, name };
458	      const sorted = sortByTabOrder(clusterTabs, tabOrder[workspace.id]);
459	      const lane = createWorkspaceLane(
460	        workspace,
461	        sorted,
462	        thumbnails,
463	        handleTabClosed,
464	        { collapsed: collapsedLanes[workspace.id] ?? false },
465	      );
466	      lane.addEventListener("workspace-reassigned", scheduleRender);
467	      container.appendChild(lane);
468	    }
469	  } else if (trulyUnsorted.length > 0) {
470	    const workspace = { id: "unsorted", name: "Unsorted" };
471	    const sorted = sortByTabOrder(trulyUnsorted, tabOrder["unsorted"]);
472	    const lane = createWorkspaceLane(
473	      workspace,
474	      sorted,
475	      thumbnails,
476	      handleTabClosed,
477	      { collapsed: collapsedLanes[workspace.id] ?? false },
478	    );
479	    lane.addEventListener("workspace-reassigned", scheduleRender);
480	    container.appendChild(lane);
481	  }
482	
483	  // 2. Meridian workspace lanes (always shown, even if empty)
484	  for (const ws of customWorkspaces) {
485	    const wsTabs = sortByTabOrder(wsTabMap.get(ws.id) ?? [], tabOrder[ws.id]);
486	    const autoRename = pendingRenameLaneId === ws.id;
487	    if (autoRename) pendingRenameLaneId = null;
488	    const lane = createWorkspaceLane(
489	      { id: ws.id, name: ws.name },
490	      wsTabs,
491	      thumbnails,
492	      handleTabClosed,
493	      {
494	        meridianWorkspace: ws,
495	        collapsed: collapsedLanes[ws.id] ?? false,
496	        autoRename,
497	      },
498	    );
499	    lane.addEventListener("workspace-reassigned", scheduleRender);
500	    container.appendChild(lane);
501	  }
502	
503	  // 3. Chrome tab group lanes
504	  for (const [groupId, tabs] of chromeGroupedMap) {
505	    const group = groupMap.get(groupId);
506	    const name = group?.title?.trim() || colorLabel(group?.color);
507	    const workspace = { id: `cg_${groupId}`, name };
508	    const autoRename = pendingRenameLaneId === workspace.id;
509	    if (autoRename) pendingRenameLaneId = null;
510	    const lane = createWorkspaceLane(
511	      workspace,
512	      tabs,
513	      thumbnails,
514	      handleTabClosed,
515	      {
516	        chromeGroup: group,
517	        collapsed: collapsedLanes[workspace.id] ?? false,
518	        autoRename,
519	      },
520	    );
521	    lane.addEventListener("workspace-reassigned", scheduleRender);
522	    container.appendChild(lane);
523	  }
524	}
