535	function buildResultRow(item) {
536	  const row = document.createElement("div");
537	  row.className = "result-row";
538	  row.tabIndex = 0;
539	
540	  const favicon = document.createElement("img");
541	  favicon.className = "result-favicon";
542	  favicon.width = 16;
543	  favicon.height = 16;
544	  favicon.src = item.favicon || "";
545	  favicon.onerror = () => {
546	    let letter = "?";
547	    try { letter = new URL(item.url).hostname.replace(/^www\./, "").charAt(0).toUpperCase() || "?"; } catch (_) {}
548	    const ph = document.createElement("span");
549	    ph.className = "favicon-placeholder";
550	    ph.textContent = letter;
551	    favicon.replaceWith(ph);
552	  };
553	
554	  const body = document.createElement("div");
555	  body.className = "result-body";
556	
557	  const title = document.createElement("div");
558	  title.className = "result-title";
559	  title.textContent = item.title || item.url;
560	
561	  const meta = document.createElement("div");
562	  meta.className = "result-meta";
563	  meta.textContent = item.url;
564	
565	  body.appendChild(title);
566	  body.appendChild(meta);
567	
568	  const context = document.createElement("div");
569	  context.className = "result-context";
570	  context.textContent = item.context || "";
571	
572	  row.appendChild(favicon);
573	  row.appendChild(body);
574	  row.appendChild(context);
575	
576	  row.addEventListener("click", () => {
577	    if (item.tabId != null) {
578	      activateTab(item.tabId);
579	    } else {
580	      openUrlFromMeridian(item.url);
581	    }
582	  });
583	
584	  row.addEventListener("keydown", (e) => {
585	    if (e.key === "Enter") row.click();
586	  });
587	
588	  return row;
589	}
