591	function renderSearchResults(results, query, scope = "all") {
592	  if (!resultsPopup) return;
593	  const container = resultsPopup.el;
594	  resultsSelection?.reset();
595	  container.innerHTML = "";
596	
597	  const sections = [
598	    { label: "Open Tabs", items: results.tabs },
599	    { label: "Bookmarks", items: results.bookmarks },
600	    { label: "History", items: results.history },
601	  ];
602	
603	  for (const { label, items } of sections) {
604	    if (!items.length) continue;
605	    const section = document.createElement("div");
606	    section.className = "search-results-section";
607	
608	    const heading = document.createElement("div");
609	    heading.className = "search-results-label";
610	    heading.id = `search-results-${label.toLowerCase().replaceAll(" ", "-")}-label`;
611	    heading.textContent = label;
612	    section.setAttribute("role", "group");
613	    section.setAttribute("aria-labelledby", heading.id);
614	    section.appendChild(heading);
615	
616	    for (const item of items.slice(0, 10)) {
617	      section.appendChild(buildResultRow(item));
618	    }
619	    container.appendChild(section);
620	  }
621	
622	  if (scope !== "all") {
623	    if (
624	      !results.tabs.length &&
625	      !results.bookmarks.length &&
626	      !results.history.length
627	    ) {
628	      const empty = document.createElement("div");
629	      empty.className = "search-results-empty";
630	      empty.textContent =
631	        scope === "bookmarks" ? "No bookmarks found" : "No history found";
632	      container.appendChild(empty);
633	    }
634	    resultsPopup.open();
635	    const count = resultsSelection?.sync?.() ?? 0;
636	    searchBarApi?.announce?.(
637	      count
638	        ? `${count} result${count === 1 ? "" : "s"} available.`
639	        : "No results found.",
640	    );
641	    return;
642	  }
643	
644	  // Web is a peer result section. With no local matches, it becomes the only
645	  // fallback section instead of showing an empty-state message.
646	  if (query) {
647	    container.appendChild(buildWebSearchSection(query));
648	  }
649	
650	  // Show the dropdown only when it actually has something to show.
651	  if (container.childElementCount > 0) {
652	    resultsPopup.open();
653	    const count = resultsSelection?.sync?.() ?? 0;
654	    searchBarApi?.announce?.(
655	      `${count} result${count === 1 ? "" : "s"} available.`,
656	    );
657	  } else {
658	    resultsPopup.close();
659	    searchBarApi?.announce?.("No results found.");
660	  }
661	}
