122	function generateSeeds(count = 12, exclude = new Set()) {
123	  const seeds = new Set();
124	  while (seeds.size < count) {
125	    const s = String(Math.floor(Math.random() * 9000) + 1000);
126	    if (!exclude.has(s)) seeds.add(s);
127	  }
128	  return [...seeds];
129	}
