688	    refreshBtn.textContent = "↻ Refresh";
689	    refreshBtn.addEventListener("click", () => {
690	      photoSeeds = generateSeeds(12, new Set(photoSeeds));
691	      renderBgSection();
692	    });
693	
694	    photoRow.appendChild(photoLabel);
695	    photoRow.appendChild(refreshBtn);
696	    bgGroup.appendChild(photoRow);
697	
698	    // ── Photo grid: 12 photos (2 rows × 6) ──
699	    const photoGrid = document.createElement("div");
700	    photoGrid.className = "settings-bg-photo-grid";
701	
702	    for (const seed of photoSeeds) {
703	      const fullUrl = `https://picsum.photos/seed/${seed}/1920/1080`;
704	      const thumbUrl = `https://picsum.photos/seed/${seed}/200/125`;
705	      photoGrid.appendChild(
706	        makeSwatch({
