711	        }),
712	      );
713	    }
714	
715	    bgGroup.appendChild(photoGrid);
716	
717	    // ── Custom image drop zone ──
718	    const uploadBtn = document.createElement("button");
719	    uploadBtn.className =
720	      "settings-bg-upload-btn" +
721	      (currentBg.type === "custom" ? " selected" : "");
722	    uploadBtn.textContent =
723	      currentBg.type === "custom"
724	        ? "✓ Custom image active — drop or click to replace"
725	        : "Drop an image here or click to upload";
726	
727	    const fileInput = document.createElement("input");
728	    fileInput.type = "file";
729	    fileInput.accept = "image/*";
730	    fileInput.className = "settings-bg-file-input";
731	    async function processCustomImage(file) {
732	      if (!file) return;
733	      uploadBtn.classList.remove("drag-over", "upload-error");
734	      if (!file.type.startsWith("image/")) {
735	        uploadBtn.classList.add("upload-error");
736	        uploadBtn.textContent = "Please choose an image file";
737	        return;
738	      }
739	      uploadBtn.disabled = true;
740	      uploadBtn.textContent = "Processing…";
741	      try {
742	        await saveCustomBackground(file);
743	        customBgUrl = await getCustomBackgroundUrl();
744	        selectBg("custom", "");
745	      } catch {
746	        uploadBtn.classList.add("upload-error");
747	        uploadBtn.textContent = "Could not save image — try another file";
748	      } finally {
749	        uploadBtn.disabled = false;
750	        fileInput.value = "";
751	      }
752	    }
753	
754	    fileInput.addEventListener("change", () =>
755	      processCustomImage(fileInput.files?.[0]),
756	    );
757	    uploadBtn.addEventListener("click", () => fileInput.click());
758	
759	    let dragDepth = 0;
760	    uploadBtn.addEventListener("dragenter", (event) => {
761	      event.preventDefault();
762	      if (uploadBtn.disabled) return;
763	      dragDepth += 1;
764	      uploadBtn.classList.add("drag-over");
765	    });
766	    uploadBtn.addEventListener("dragover", (event) => {
767	      event.preventDefault();
768	      if (uploadBtn.disabled) return;
769	      event.dataTransfer.dropEffect = "copy";
770	      uploadBtn.classList.add("drag-over");
771	    });
772	    uploadBtn.addEventListener("dragleave", (event) => {
773	      event.preventDefault();
774	      dragDepth = Math.max(0, dragDepth - 1);
775	      if (dragDepth === 0) uploadBtn.classList.remove("drag-over");
776	    });
777	    uploadBtn.addEventListener("drop", (event) => {
778	      event.preventDefault();
779	      dragDepth = 0;
780	      uploadBtn.classList.remove("drag-over");
781	      if (uploadBtn.disabled) return;
782	      processCustomImage(event.dataTransfer.files?.[0]);
783	    });
784	
785	    bgGroup.appendChild(fileInput);
786	    bgGroup.appendChild(uploadBtn);
787	  }
788	
789	  appearanceSection.appendChild(bgGroup);
790	
791	  // --- Refresh thumbnails (a group under Tabs, at the bottom of the panel) ---
792	  const refreshGroup = document.createElement("div");
793	  refreshGroup.className = "settings-group";
794	
795	  const refreshLabel = document.createElement("span");
796	  refreshLabel.className = "settings-label";
797	  refreshLabel.textContent = "Thumbnails";
798	  refreshGroup.appendChild(refreshLabel);
799	
800	  const refreshBtn = document.createElement("button");
801	  refreshBtn.className = "settings-action-btn";
802	  refreshBtn.textContent = "Refresh all thumbnails (this will cycle tabs)";
803	  refreshBtn.addEventListener("click", async () => {
804	    refreshBtn.disabled = true;
805	    refreshBtn.textContent = "Refreshing…";
806	    await chrome.runtime.sendMessage({ type: "REFRESH_THUMBNAILS" });
807	    refreshBtn.textContent = "Done";
808	    setTimeout(() => {
809	      refreshBtn.disabled = false;
810	      refreshBtn.textContent = "Refresh all thumbnails (this will cycle tabs)";
811	    }, 2000);
812	  });
813	  refreshGroup.appendChild(refreshBtn);
814	  tabsSection.appendChild(refreshGroup);
815	
816	  // Keep the optional Privacy & Data disclosure last so primary settings
817	  // remain immediately available.
818	  panel.append(appearanceSection, searchSection, tabsSection, privacySection);
819	
820	  container.appendChild(panel);
821	
822	  chrome.storage.sync
823	    .get([
824	      "newTabBehavior",
825	      "groupByDomain",
826	      "homepageUrl",
827	      "theme",
828	      "background",
829	      "localSearch",
830	      "searchProvider",
831	    ])
832	    .then((saved) => {
833	      if (saved.newTabBehavior) newTabBehavior = saved.newTabBehavior;
834	      groupByDomain = !!saved.groupByDomain;
835	      homepageUrl = saved.homepageUrl ?? "";
836	      currentTheme = saved.theme ?? "system";
837	      currentBg = saved.background ?? DEFAULT_BACKGROUND;
838	      toggleCheckbox.checked = groupByDomain;
839	      if (currentBg.type === "custom") {
840	        const background = currentBg;
841	        const customUrlPromise = getCustomBackgroundUrl();
842	        applyAccentFromBackground(background, customUrlPromise);
843	        customUrlPromise.then((url) => {
844	          customBgUrl = url;
845	          if (currentBg !== background) return;
846	          applyBackground(background, customBgUrl);
847	          renderBgSection();
848	        });
849	      }
850	      if (saved.localSearch) {
851	        localSearch = { ...localSearch, ...saved.localSearch };
852	      }
853	      syncLocalSearchCheckboxes(saved.localSearch);
854	      if (
855	        saved.searchProvider &&
856	        PROVIDERS.some((p) => p.id === saved.searchProvider)
857	      ) {
858	        searchProvider = saved.searchProvider;
859	      }
860	      syncNewTab();
861	      renderThemeButtons();
862	      renderBgSection();
863	      renderProviderCards();
864	    });
865	
866	  syncNewTab();
867	  renderThemeButtons();
868	  renderBgSection();
869	  renderProviderCards();
870	}
871	
872	// ── Auto accent: derive the accent hue from the active background ──
873	// The accent tracks the background's dominant hue; the theme keeps saturation
874	// and lightness (see meridian.css), and a contrast guard nudges lightness so
875	// the accent can never collapse into a same-toned solid background.
876	
877	function hexToRgb(hex) {
878	  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex).trim());
879	  if (!m) return null;
880	  let h = m[1];
881	  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
882	  const int = parseInt(h, 16);
883	  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
884	}
885	
886	function rgbToHsl(r, g, b) {
887	  r /= 255;
888	  g /= 255;
889	  b /= 255;
890	  const max = Math.max(r, g, b);
891	  const min = Math.min(r, g, b);
892	  const l = (max + min) / 2;
893	  const d = max - min;
894	  let h = 0;
895	  let s = 0;
896	  if (d !== 0) {
897	    s = d / (1 - Math.abs(2 * l - 1));
898	    if (max === r) h = ((g - b) / d) % 6;
899	    else if (max === g) h = (b - r) / d + 2;
900	    else h = (r - g) / d + 4;
901	    h = Math.round(h * 60);
902	    if (h < 0) h += 360;
903	  }
904	  return { h, s: Math.round(s * 100), l: Math.round(l * 100) };
905	}
906	
907	// Pick the most saturated stop of a gradient/solid — the color that gives
908	// the background its identity, not the muddy average of all stops.
909	function dominantHex(str) {
910	  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
911	  if (!hexes || !hexes.length) return null;
912	  let best = null;
913	  for (const hx of hexes) {
914	    const rgb = hexToRgb(hx);
915	    if (!rgb) continue;
916	    const hsl = rgbToHsl(...rgb);
917	    if (!best || hsl.s > best.s) best = hsl;
918	  }
919	  return best;
920	}
921	
922	// Find an image's dominant *vivid* hue via a saturation-weighted histogram.
923	// A plain pixel average collapses to gray and throws the real color away.
924	// Also returns the image's overall luminance (all opaque pixels) so callers
925	// can decide whether content sitting on it needs light or dark text.
926	function analyzeImage(url) {
927	  return new Promise((resolve) => {
928	    const img = new Image();
929	    img.crossOrigin = "anonymous";
930	    img.onload = () => {
931	      try {
932	        const size = 48;
933	        const canvas = document.createElement("canvas");
934	        canvas.width = size;
935	        canvas.height = size;
936	        const ctx = canvas.getContext("2d");
937	        ctx.drawImage(img, 0, 0, size, size);
938	        const { data } = ctx.getImageData(0, 0, size, size);
939	        const BINS = 24;
940	        const weight = new Array(BINS).fill(0);
941	        const sSum = new Array(BINS).fill(0);
942	        const lSum = new Array(BINS).fill(0);
943	        const count = new Array(BINS).fill(0);
944	        let lumSum = 0;
945	        let lumN = 0;
946	        for (let i = 0; i < data.length; i += 4) {
947	          if (data[i + 3] < 125) continue;
948	          lumSum += relLum(data[i], data[i + 1], data[i + 2]);
949	          lumN += 1;
950	          const hsl = rgbToHsl(data[i], data[i + 1], data[i + 2]);
951	          // Skip grays and near black/white — they carry no hue identity.
952	          if (hsl.s < 18 || hsl.l < 10 || hsl.l > 92) continue;
953	          const bin = Math.floor((hsl.h / 360) * BINS) % BINS;
954	          weight[bin] += hsl.s / 100; // vivid pixels weigh more
955	          sSum[bin] += hsl.s;
956	          lSum[bin] += hsl.l;
957	          count[bin] += 1;
958	        }
959	        const lum = lumN ? lumSum / lumN : null;
960	        let top = -1;
961	        let topW = 0;
962	        for (let b = 0; b < BINS; b += 1) {
963	          if (weight[b] > topW) {
964	            topW = weight[b];
965	            top = b;
966	          }
967	        }
968	        if (top < 0) return resolve({ dominant: null, lum }); // no vivid pixels
969	        resolve({
970	          dominant: {
971	            h: Math.round(((top + 0.5) / BINS) * 360),
972	            s: Math.round(sSum[top] / count[top]),
973	            l: Math.round(lSum[top] / count[top]),
974	          },
975	          lum,
976	        });
977	      } catch {
978	        resolve({ dominant: null, lum: null }); // cross-origin taint, etc.
979	      }
980	    };
981	    img.onerror = () => resolve({ dominant: null, lum: null });
982	    img.src = url;
983	  });
984	}
985	
986	// Average relative luminance across every hex stop in a string.
987	function averageLumOfHexes(str) {
988	  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
989	  if (!hexes || !hexes.length) return null;
990	  let sum = 0;
991	  let n = 0;
992	  for (const hx of hexes) {
993	    const rgb = hexToRgb(hx);
994	    if (!rgb) continue;
995	    sum += relLum(...rgb);
996	    n += 1;
997	  }
998	  return n ? sum / n : null;
999	}
1000	
1001	// Returns { dominant, lum } for the active background. `lum` is null for the
1002	// "none" background, which follows the theme's --bg (read live at apply time).
1003	async function analyzeBackground(bg, customDataUrl) {
1004	  if (!bg || bg.type === "none") return { dominant: null, lum: null };
1005	  if (bg.type === "solid") {
1006	    const rgb = hexToRgb(bg.value);
1007	    return {
1008	      dominant: rgb ? rgbToHsl(...rgb) : null,
1009	      lum: rgb ? relLum(...rgb) : null,
1010	    };
1011	  }
1012	  if (bg.type === "gradient") {
1013	    return { dominant: dominantHex(bg.value), lum: averageLumOfHexes(bg.value) };
1014	  }
1015	  if (bg.type === "photo") return analyzeImage(bg.value);
1016	  if (bg.type === "custom") {
1017	    return customDataUrl
1018	      ? analyzeImage(customDataUrl)
1019	      : { dominant: null, lum: null };
1020	  }
1021	  return { dominant: null, lum: null };
1022	}
1023	
1024	// ── Color math for the surface-contrast solver ──
1025	function hslToRgb(h, s, l) {
1026	  s /= 100;
1027	  l /= 100;
1028	  const c = (1 - Math.abs(2 * l - 1)) * s;
1029	  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
1030	  const m = l - c / 2;
1031	  let r = 0;
1032	  let g = 0;
1033	  let b = 0;
1034	  if (h < 60) [r, g, b] = [c, x, 0];
1035	  else if (h < 120) [r, g, b] = [x, c, 0];
1036	  else if (h < 180) [r, g, b] = [0, c, x];
1037	  else if (h < 240) [r, g, b] = [0, x, c];
1038	  else if (h < 300) [r, g, b] = [x, 0, c];
1039	  else [r, g, b] = [c, 0, x];
1040	  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];
1041	}
1042	
1043	function relLum(r, g, b) {
1044	  const a = [r, g, b].map((v) => {
1045	    const n = v / 255;
1046	    return n <= 0.03928 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
1047	  });
1048	  return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
1049	}
1050	
1051	function contrastRatio(l1, l2) {
1052	  const hi = Math.max(l1, l2);
1053	  const lo = Math.min(l1, l2);
1054	  return (hi + 0.05) / (lo + 0.05);
1055	}
1056	
1057	// Luminance of the actual --surface the accent renders on (cards, panels).
1058	function surfaceLum() {
1059	  const v = getComputedStyle(document.documentElement)
1060	    .getPropertyValue("--surface")
1061	    .trim();
1062	  const rgb = hexToRgb(v);
1063	  if (rgb) return relLum(...rgb);
1064	  return docIsDark() ? 0.035 : 1;
1065	}
1066	
1067	// Derived accents run a touch under full saturation — neon reads cheap.
1068	const ACCENT_SAT = 80;
1069	
1070	// Last resolved dominant + background luminance, cached so a theme switch can
1071	// re-run the solver and re-pick on-background text without re-sampling.
1072	let lastDominant = null;
1073	let lastBgLum = null;
1074	let accentGeneration = 0;
1075	
1076	function docIsDark() {
1077	  const t = document.documentElement.dataset.theme;
1078	  if (t === "dark") return true;
1079	  if (t === "light") return false;
1080	  return window.matchMedia("(prefers-color-scheme: dark)").matches;
1081	}
1082	
1083	function applyDerivedAccent(dominant) {
1084	  const root = document.documentElement;
1085	  // Grayscale / very desaturated → no meaningful hue; use the default.
1086	  if (!dominant || dominant.s < 12) {
1087	    root.style.removeProperty("--accent-hue");
1088	    root.style.removeProperty("--accent-sat");
1089	    root.style.removeProperty("--accent-light");
1090	    return;
1091	  }
1092	
1093	  // Solve for a lightness that clears a legible contrast against the SURFACE
1094	  // (where the accent actually lives), searching in the safe direction and
1095	  // staying inside a tasteful band so filled-accent glyphs stay readable too.
1096	  const hue = dominant.h;
1097	  const dark = docIsDark();
1098	  const surf = surfaceLum();
1099	  const target = 3.5;
1100	  const floor = dark ? 48 : 30;
1101	  const ceil = dark ? 70 : 50;
1102	  let l = dark ? 58 : 44;
1103	  const step = dark ? 2 : -2;
1104	  for (let i = 0; i < 40; i += 1) {
1105	    const [r, g, b] = hslToRgb(hue, ACCENT_SAT, l);
1106	    if (contrastRatio(relLum(r, g, b), surf) >= target) break;
1107	    l += step;
1108	    if (l <= floor) {
1109	      l = floor;
1110	      break;
1111	    }
1112	    if (l >= ceil) {
1113	      l = ceil;
1114	      break;
1115	    }
1116	  }
1117	
1118	  root.style.setProperty("--accent-hue", String(hue));
1119	  root.style.setProperty("--accent-sat", `${ACCENT_SAT}%`);
1120	  root.style.setProperty("--accent-light", `${l}%`);
1121	}
1122	
1123	// Content that sits directly on the background (lane headers) can't rely on the
1124	// theme's text color — the wallpaper may be light or dark regardless of theme.
1125	// Pick light or dark on-background text from the background's own luminance,
1126	// plus a contrasting text-shadow scrim so it survives busy photos.
1127	function applyOnBackground(lum) {
1128	  const root = document.documentElement;
1129	  let L = lum;
1130	  if (L == null) {
1131	    // "none" background follows the theme's --bg — read it live.
1132	    const v = getComputedStyle(root).getPropertyValue("--bg").trim();
1133	    const rgb = hexToRgb(v);
1134	    L = rgb ? relLum(...rgb) : docIsDark() ? 0.02 : 0.9;
1135	  }
1136	  if (L < 0.4) {
1137	    // Dark background → light text.
1138	    root.style.setProperty("--on-bg", "rgba(255, 255, 255, 0.95)");
1139	    root.style.setProperty("--on-bg-muted", "rgba(255, 255, 255, 0.72)");
1140	    root.style.setProperty("--on-bg-shadow", "0 1px 3px rgba(0, 0, 0, 0.55)");
1141	  } else {
1142	    // Light background → dark text.
1143	    root.style.setProperty("--on-bg", "rgba(0, 0, 0, 0.9)");
1144	    root.style.setProperty("--on-bg-muted", "rgba(0, 0, 0, 0.6)");
1145	    root.style.setProperty("--on-bg-shadow", "0 1px 2px rgba(255, 255, 255, 0.4)");
1146	  }
1147	}
1148	
1149	export async function applyAccentFromBackground(bg, customDataUrl = null) {
1150	  const generation = ++accentGeneration;
1151	  const resolvedCustomDataUrl = await customDataUrl;
1152	  if (generation !== accentGeneration) return;
1153	
1154	  const { dominant, lum } = await analyzeBackground(bg, resolvedCustomDataUrl);
1155	  if (generation !== accentGeneration) return;
1156	
1157	  lastDominant = dominant;
1158	  lastBgLum = lum;
1159	  applyDerivedAccent(dominant);
1160	  applyOnBackground(lum);
1161	}
1162	
1163	export function applyTheme(theme) {
1164	  const html = document.documentElement;
1165	  if (theme === "light") {
1166	    html.dataset.theme = "light";
1167	  } else if (theme === "dark") {
1168	    html.dataset.theme = "dark";
1169	  } else {
1170	    delete html.dataset.theme;
1171	  }
1172	  // Both the accent solver and the on-background text depend on the theme
1173	  // (surface + the "none" background follow it) — re-run them on switch.
1174	  applyDerivedAccent(lastDominant);
1175	  applyOnBackground(lastBgLum);
1176	}
1177	
1178	export function applyBackground(bg, customDataUrl = null) {
1179	  const root = document.documentElement;
1180	  root.style.removeProperty("--bg");
1181	  if (!bg || bg.type === "none") {
1182	    root.style.removeProperty("--bg-image");
1183	  } else if (bg.type === "solid") {
1184	    root.style.removeProperty("--bg-image");
1185	    root.style.setProperty("--bg", bg.value);
1186	  } else if (bg.type === "gradient") {
1187	    root.style.setProperty("--bg-image", bg.value);
1188	  } else if (bg.type === "photo") {
1189	    root.style.setProperty("--bg-image", `url("${bg.value}")`);
1190	  } else if (bg.type === "custom") {
1191	    if (customDataUrl) {
1192	      root.style.setProperty("--bg-image", `url("${customDataUrl}")`);
1193	    } else {
1194	      root.style.removeProperty("--bg-image");
1195	    }
1196	  }
1197	}
